import{_ as e,o as t,c as n,a7 as i}from"./chunks/framework.BCbKzsgW.js";const m=JSON.parse('{"title":"身份与访问管理（IAM）","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"development/common/authentication/index.md","filePath":"development/common/authentication/index.md","lastUpdated":1793703140000}'),h={name:"development/common/authentication/index.md"};function l(o,a,r,d,s,u){return t(),n("div",null,[...a[0]||(a[0]=[i('<h1 id="shen-fen-yu-fang-wen-guan-liiam" tabindex="-1">身份与访问管理（IAM） <a class="header-anchor" href="#shen-fen-yu-fang-wen-guan-liiam" aria-label="Permalink to &quot;身份与访问管理（IAM）&quot;">​</a></h1><p><strong>身份与访问管理</strong>（Identity and Access Management，IAM）管理主体的身份、凭据与访问权限，涉及账号开通、登录认证、授权、身份联合和访问撤销。<a href="https://www.microsoft.com/zh-cn/security/business/security-101/what-is-identity-access-management-iam" target="_blank" rel="noreferrer">Microsoft 的 IAM 介绍</a>将身份生命周期与访问管理纳入同一体系；用户认证是其中验证身份的一环。</p><p>只实现“密码正确后返回一个 Token”，还没有形成可以持续运行的身份与权限体系。账号关联、设备管理、角色分配、离职停权与恢复，都需要和登录状态、资源权限保持一致。</p><p>专题以面向浏览器和移动端的业务系统为背景，讨论普通用户、企业成员与管理人员的身份。实名认证、支付风控和机器身份只说明边界，不展开行业合规规则或服务间认证协议。</p><h2 id="shen-fenren-zhengshou-quan-yu-shen-ji" tabindex="-1">身份、认证、授权与审计 <a class="header-anchor" href="#shen-fenren-zhengshou-quan-yu-shen-ji" aria-label="Permalink to &quot;身份、认证、授权与审计&quot;">​</a></h2><p>IAM 中的几类职责需要分别设计：</p><table tabindex="0"><thead><tr><th>职责</th><th>输入</th><th>输出</th></tr></thead><tbody><tr><td>身份管理：主体是谁、是否仍有效</td><td>注册、邀请、组织目录与成员变更</td><td>账号、身份关联与成员生命周期状态</td></tr><tr><td>认证：请求代表谁</td><td>密码、认证器、会话或令牌</td><td>已验证的主体与认证上下文</td></tr><tr><td>授权：能否执行操作</td><td>主体、租户、资源、动作与业务状态</td><td>允许或拒绝</td></tr><tr><td>审计：发生过什么</td><td>操作者、结果、目标、时间与追踪标识</td><td>可追溯的安全事件</td></tr></tbody></table><p>例如“企业管理员删除成员”：身份管理维护管理员和目标成员的状态；登录解决操作者身份；授权检查其当前企业角色；业务逻辑处理最后一名管理员等约束；审计记录谁在何时删除了谁。把 <code>is_admin</code> 写进长期令牌，无法完整表达这些条件。</p><h2 id="zhuan-ti-wen-zhang" tabindex="-1">专题文章 <a class="header-anchor" href="#zhuan-ti-wen-zhang" aria-label="Permalink to &quot;专题文章&quot;">​</a></h2><h3 id="zhang-hao-yu-deng-lu-zhuang-tai" tabindex="-1">账号与登录状态 <a class="header-anchor" href="#zhang-hao-yu-deng-lu-zhuang-tai" aria-label="Permalink to &quot;账号与登录状态&quot;">​</a></h3><ul><li><a href="./fundamentals.html">认证边界与方案选择</a>：身份、凭据、会话与令牌的关系，以及不同客户端的架构选择。</li><li><a href="./account-lifecycle.html">账号模型与生命周期</a>：账号、登录标识、外部身份、成员关系、绑定、合并与注销。</li><li><a href="./password.html">密码、验证码与账号恢复</a>：密码存储、登录限流、验证码消费与恢复事务。</li><li><a href="./session.html">Cookie、Session 与设备管理</a>：浏览器行为、会话轮换、超时、多设备退出与缓存一致性。</li><li><a href="./token-jwt.html">Token、JWT 与刷新撤销</a>：令牌验证、刷新轮换、重用检测与密钥管理。</li></ul><h3 id="shen-fen-lian-he-yu-quan-xian-bian-jie" tabindex="-1">身份联合与权限边界 <a class="header-anchor" href="#shen-fen-lian-he-yu-quan-xian-bian-jie" aria-label="Permalink to &quot;身份联合与权限边界&quot;">​</a></h3><ul><li><a href="./oauth-oidc.html">OAuth 2.0 与 OpenID Connect</a>：授权码、PKCE、回调校验和第三方账号映射。</li><li><a href="./sso.html">单点登录与企业身份接入</a>：独立应用会话、统一退出、成员开通与离职撤权。</li><li><a href="./mfa-passkey.html">多因素认证与 Passkey</a>：TOTP、WebAuthn、提升认证强度和认证器恢复。</li><li><a href="./authorization.html">授权、角色与多租户隔离</a>：角色、属性、关系、访问控制列表，以及对象级权限。</li></ul><h3 id="gong-cheng-luo-di" tabindex="-1">工程落地 <a class="header-anchor" href="#gong-cheng-luo-di" aria-label="Permalink to &quot;工程落地&quot;">​</a></h3><ul><li><a href="./security-operations.html">安全防护、审计与运行保障</a>：威胁对应的防线、日志、故障策略、指标与验证。</li><li><a href="./system-design.html">IAM 系统参考设计</a>：组合前述机制，给出数据约束、接口契约与关键事务。</li></ul><h2 id="jia-gou-xuan-ze-de-qi-dian" tabindex="-1">架构选择的起点 <a class="header-anchor" href="#jia-gou-xuan-ze-de-qi-dian" aria-label="Permalink to &quot;架构选择的起点&quot;">​</a></h2><p>对于自有浏览器业务，优先评估服务端 Session 与同源后端；多种客户端、第三方 API 委托访问或跨组织身份接入，再引入对应协议。系统需要 OIDC 时，可以接入成熟身份提供方，应用继续维护本地账号、成员和资源权限。</p><p>这是一项工程取舍：集中保存状态便于撤销，但增加在线存储依赖；本地验证令牌减少查询，但必须承受或补偿权限与账号状态的传播延迟。具体比较见<a href="./fundamentals.html">认证边界与方案选择</a>。</p><h2 id="guan-chuan-zhuan-ti-de-she-ji-yue-shu" tabindex="-1">贯穿专题的设计约束 <a class="header-anchor" href="#guan-chuan-zhuan-ti-de-she-ji-yue-shu" aria-label="Permalink to &quot;贯穿专题的设计约束&quot;">​</a></h2><ol><li>内部账号 ID 稳定，邮箱、手机号和外部登录方式可以变化。</li><li>“登录成功”“通过第二因素”“有权访问当前租户”分别判断。</li><li>密码重置、封禁与退出必须定义已有会话如何失效。</li><li>注册、验证码消费、账号绑定和刷新轮换都处理并发与重复请求。</li></ol><h2 id="can-kao-zi-liao" tabindex="-1">参考资料 <a class="header-anchor" href="#can-kao-zi-liao" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li>Microsoft：<a href="https://www.microsoft.com/zh-cn/security/business/security-101/what-is-identity-access-management-iam" target="_blank" rel="noreferrer">什么是标识和访问管理（IAM）？</a></li></ul>',22)])])}const f=e(h,[["render",l]]);export{m as __pageData,f as default};
